import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Infernalis (Day 1) -- CephFS && OpenStack","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- CephFS && OpenStack","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["CephFS","OpenStack","Manila","Multi","tenancy","OpenStack Integration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_CephFS_OpenStack.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_CephFS_OpenStack.md","lastUpdated":1780459816000}'),e={name:"posts/2015/CDS_Infernalis_Day_1_--_CephFS_OpenStack.md"};function o(p,l,r,s,S,_){return t(),a("div",null,[...l[0]||(l[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： SEFS 多租户特性及 OpenStack 相关议题</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Sage、Danny、Josh、Mark 等</p><p><strong>会议内容</strong>：</p><p><strong>一、OpenStack 相关议题</strong></p><ol><li><p><strong>第三方测试</strong>：</p><ul><li>目前 OpenStack 代码库中缺乏第三方测试支持，需要建立测试环境并在代码提交或审查时进行测试。</li><li>建议由 Red Hat OpenStack 团队、Marantis、Canonical 等组织承担测试工作，并将 SEFS 测试集成到其测试中。</li></ul></li><li><p><strong>SEFS for Manila</strong>：</p><ul><li>讨论了三种将 SEFS 与 Manila 集成的方法： <ul><li>使用默认驱动程序，将卷映射到 Manila VM 并导出 NFS。</li><li>使用 Ganesha 驱动程序，将现有共享文件系统重新导出为 NFS。</li><li>开发原生驱动程序，使客户机直接映射 SEFS 文件系统。</li></ul></li><li>建议使用 Ganesha 驱动程序，因为它提供了网络隔离和多租户支持。</li><li>需要解决 Manila 对共享文件系统功能的要求，例如快照和克隆，以及与 Swift 对象存储兼容性问题。</li></ul></li><li><p><strong>Swift 兼容性</strong>：</p><ul><li>SEFS 与 Swift 的兼容性存在一些差距，例如命名空间处理、对象版本和过期等。</li><li>建议更新 Swift 测试套件，并修复 Swift 兼容性相关的缺陷。</li><li>可以考虑实现 Swift 对象版本，但优先级较低。</li></ul></li></ol><p><strong>二、多租户特性</strong></p><ol><li><p><strong>安全</strong>：</p><ul><li>需要实现以下安全特性： <ul><li>读取权限</li><li>根权限限制</li><li>基于路径的挂载限制</li><li>数据路径安全</li><li>命名空间隔离</li></ul></li></ul></li><li><p><strong>性能</strong>：</p><ul><li>需要优化性能，例如减少网络跳数和优化数据路径。</li></ul></li></ol><p><strong>三、行动计划</strong></p><ol><li>搭建 OpenStack 测试环境，并集成 SEFS 测试。</li><li>开发 Ganesha 驱动程序，并将其集成到 Manila 中。</li><li>更新 Swift 测试套件，并修复 Swift 兼容性缺陷。</li><li>实现多租户安全特性。</li><li>优化 SEFS 性能。</li></ol><p><strong>四、其他</strong></p><ol><li>需要收集用户对多租户功能的需求，以便确定优先级。</li><li>需要考虑在多租户环境下共享数据的问题。</li></ol><p>[改进后的总结中保留了以下关键词]：</p><ul><li>CephFS</li><li>OpenStack</li><li>Manila</li><li>Multi-tenancy</li><li>OpenStack Integration</li><li>SEFS</li><li>Ganesha driver</li><li>Swift</li><li>Security</li><li>Performance</li><li>Testing</li><li>Compatibility</li><li>Storage Cluster</li><li>Cloud Computing</li></ul>',15)])])}const u=i(e,[["render",o]]);export{g as __pageData,u as default};
